(()=>{function wire(){document.querySelectorAll('[data-copy-url]').forEach(b=>{if(b.dataset.wired)return;b.dataset.wired='1';b.addEventListener('click',async()=>{const u=b.dataset.copyUrl||location.href,old=b.textContent;try{await navigator.clipboard.writeText(u);b.textContent='Copied';setTimeout(()=>b.textContent=old,1400)}catch{prompt('Copy this link',u)}})})}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',wire,{once:true}):wire()})();
